var t=`0232-spanakopita`;var i=`world-0232`;var a=`GR`;var o=`southern-europe`;var r=4;var s=61;var l={en:`Spanakopita`,ua:`Спанакопіта`};var g={en:`A traditional Greece dish made with spinach, green onion, dill, feta. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: шпинат, зелена цибуля, кріп, фета. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`spinach`,700,`g`],[`green-onion`,160,`g`],[`extra-virgin-olive-oil`,35,`ml`],[`dill`,25,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:6,i:[[`feta`,300,`g`],[`chicken-egg`,2,`pcs`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:12,i:[[`phyllo-pastry`,350,`g`],[`unsalted-butter`,110,`g`]]},{en:`Bake in a preheated 180°C oven for about 35 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 35 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:35,i:[]}];var h={slug:t,id:i,country:`GR`,region:o,servings:4,minutes:61,title:l,text:g,steps:d};export{a as country,h as default,i as id,s as minutes,o as region,r as servings,t as slug,d as steps,g as text,l as title};